Solution A: ```javascript
function playSpaceInvaders(canvasId) {
    const canvas = document.getElementById(canvasId);
    canvas.width = canvas.height = 500;
    const ctx = canvas.getContext('2d');

    const keys = { arrowLeft: false, arrowRight: false, space: false };

    window.addEventListener('keydown', e => {
        if (e.code === 'ArrowLeft') keys.arrowLeft = true;
        if (e.code === 'ArrowRight') keys.arrowRight = true;
        if (e.code === 'Space') keys.space = true;
    });
    window.addEventListener('keyup', e => {
        if (e.code === 'ArrowLeft') keys.arrowLeft = false;
        if (e.code === 'ArrowRight') keys.arrowRight = false;
        if (e.code === 'Space') keys.space = false;
    });

    const player = {
        x: 250, y: 460, w: 20, h: 20, color: '#0f0', speed: 6
    };
    const playerBullets = [];
    const enemyBullets = [];
    const enemies = [];
    const explosions = [];
    let score = 0, level = 1;
    let gameOver = false, win = false;
    let enemyDirection = 1; // 1 right, -1 left
    let enemySpeed = 1;
    let enemyFireTimer = 0;
    const enemyFireInterval = 120; // frames
    const enemyRows = 5, enemyCols = 11;
    const enemyGap = 5;
    const enemySize = 20;
    const enemyOffsetX = 40, enemyOffsetY = 40;
    const maxEnemySpeed = 3;

    function spawnEnemies() {
        enemies.length = 0;
        for (let r = 0; r < enemyRows; r++) {
            for (let c = 0; c < enemyCols; c++) {
                enemies.push({
                    x: enemyOffsetX + c * (enemySize + enemyGap),
                    y: enemyOffsetY + r * (enemySize + enemyGap),
                    w: enemySize, h: enemySize,
                    color: '#ff0'
                });
            }
        }
    }
    spawnEnemies();

    function update() {
        if (gameOver) return;
        // Player movement
        if (keys.arrowLeft && player.x > 0) player.x -= player.speed;
        if (keys.arrowRight && player.x < canvas.width - player.w) player.x += player.speed;
        // Player shooting
        if (keys.space && !player.canShoot) {
            playerBullets.push({ x: player.x + player.w / 2 - 2, y: player.y, w: 4, h: 10, dy: -8, color: '#fff' });
            player.canShoot = true;
        }
        if (!keys.space) player.canShoot = false;

        // Update bullets
        for (let i = playerBullets.length - 1; i >= 0; i--) {
            const b = playerBullets[i];
            b.y += b.dy;
            if (b.y < 0) playerBullets.splice(i, 1);
        }
        for (let i = enemyBullets.length - 1; i >= 0; i--) {
            const b = enemyBullets[i];
            b.y += b.dy;
            if (b.y > canvas.height) enemyBullets.splice(i, 1);
        }

        // Enemy movement
        let hitEdge = false;
        for (const e of enemies) {
            e.x += enemyDirection * enemySpeed;
            if (e.x <= 0 || e.x + e.w >= canvas.width) hitEdge = true;
        }
        if (hitEdge) {
            enemyDirection *= -1;
            for (const e of enemies) e.y += enemySize / 2;
        }

        // Enemy shooting
        enemyFireTimer++;
        if (enemyFireTimer >= enemyFireInterval) {
            enemyFireTimer = 0;
            const target = enemies[Math.floor(Math.random() * enemies.length)];
            if (target) {
                enemyBullets.push({ x: target.x + target.w / 2 - 2, y: target.y + target.h, w: 4, h: 10, dy: 5, color: '#f00' });
            }
        }

        // Collision detection
        // Player bullets vs enemies
        for (let i = playerBullets.length - 1; i >= 0; i--) {
            const b = playerBullets[i];
            for (let j = enemies.length - 1; j >= 0; j--) {
                const e = enemies[j];
                if (b.x < e.x + e.w && b.x + b.w > e.x && b.y < e.y + e.h && b.y + b.h > e.y) {
                    // Hit
                    playerBullets.splice(i, 1);
                    enemies.splice(j, 1);
                    score += 10;
                    explosions.push({ x: e.x, y: e.y, size: enemySize, frames: 15, color: '#ff0' });
                    break;
                }
            }
        }
        // Enemy bullets vs player
        for (let i = enemyBullets.length - 1; i >= 0; i--) {
            const b = enemyBullets[i];
            if (b.x < player.x + player.w && b.x + b.w > player.x && b.y < player.y + player.h && b.y + b.h > player.y) {
                enemyBullets.splice(i, 1);
                explosions.push({ x: player.x, y: player.y, size: 20, frames: 15, color: '#f00' });
                gameOver = true;
                break;
            }
        }

        // Enemies reach bottom
        for (const e of enemies) {
            if (e.y + e.h >= canvas.height) {
                gameOver = true;
                break;
            }
        }

        // Win condition
        if (enemies.length === 0) {
            win = true;
            level++;
            enemySpeed = Math.min(maxEnemySpeed, enemySpeed + 0.5);
            spawnEnemies();
        }

        // Update explosions
        for (let i = explosions.length - 1; i >= 0; i--) {
            const ex = explosions[i];
            ex.frames--;
            if (ex.frames <= 0) explosions.splice(i, 1);
        }
    }

    function draw() {
        ctx.clearRect(0, 0, canvas.width, canvas.height);

        // Draw player
        ctx.fillStyle = player.color;
        ctx.fillRect(player.x, player.y, player.w, player.h);

        // Draw bullets
        for (const b of playerBullets) {
            ctx.fillStyle = b.color;
            ctx.fillRect(b.x, b.y, b.w, b.h);
        }
        for (const b of enemyBullets) {
            ctx.fillStyle = b.color;
            ctx.fillRect(b.x, b.y, b.w, b.h);
        }

        // Draw enemies
        for (const e of enemies) {
            ctx.fillStyle = e.color;
            ctx.fillRect(e.x, e.y, e.w, e.h);
        }

        // Draw explosions
        for (const ex of explosions) {
            ctx.fillStyle = ex.color;
            ctx.fillRect(ex.x, ex.y, ex.size, ex.size);
        }

        // Draw score and level
        ctx.fillStyle = '#fff';
        ctx.font = '16px Arial';
        ctx.fillText('Score: ' + score, 10, 20);
        ctx.fillText('Level: ' + level, 10, 40);

        // Game over
        if (gameOver) {
            ctx.fillStyle = 'rgba(0,0,0,0.5)';
            ctx.fillRect(0, 0, canvas.width, canvas.height);
            ctx.fillStyle = '#fff';
            ctx.font = '30px Arial';
            ctx.textAlign = 'center';
            ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2);
        }
        if (win) {
            ctx.fillStyle = 'rgba(0,0,0,0.5)';
            ctx.fillRect(0, 0, canvas.width, canvas.height);
            ctx.fillStyle = '#fff';
            ctx.font = '30px Arial';
            ctx.textAlign = 'center';
            ctx.fillText('Level ' + level + ' Clear!', canvas.width / 2, canvas.height / 2 - 20);
            ctx.fillText('Press F5 to restart', canvas.width / 2, canvas.height / 2 + 20);
        }
    }

    function loop() {
        update();
        draw();
        requestAnimationFrame(loop);
    }

    loop();
}
